import type { Request } from '../router.ts';
import type { AppContext, User } from '../types.ts';
import { findSession } from './sessions.ts';

export function bearerToken(req: Pick<Request, 'headers'>): string | null {
  const header = req.headers.authorization;
  if (!header?.startsWith('Bearer ')) return null;
  return header.slice('Bearer '.length).trim() || null;
}

/** Resolve the user behind a request's bearer token, or null. */
export function authenticateRequest(ctx: AppContext, req: Pick<Request, 'headers'>): User | null {
  const token = bearerToken(req);
  if (!token) return null;
  const session = findSession(ctx, token);
  if (!session) return null;
  return ctx.store.users.get(session.userId) ?? null;
}
import { asBody, requireString } from '../lib/validate.ts';
import { unauthorized } from '../lib/errors.ts';
import { noContent, ok } from '../router.ts';
import type { Handler } from '../router.ts';
import { findByEmail } from '../users/service.ts';
import { verifyPassword } from './password.ts';
import { bearerToken } from './guard.ts';
import { createSession, destroySession, purgeExpiredSessions } from './sessions.ts';

export const login: Handler = (req, ctx) => {
  const body = asBody(req.body);
  const email = requireString(body, 'email');
  const password = requireString(body, 'password');
  const user = findByEmail(ctx, email);
  if (!user || !verifyPassword(password, user.passwordHash, user.passwordSalt, ctx.config.passwordCost)) {
    throw unauthorized('invalid email or password');
  }
  const session = createSession(ctx, user.id);
  return ok({ token: session.id, expiresAt: session.expiresAt });
};

export const logout: Handler = (req, ctx) => {
  const token = bearerToken(req);
  if (token) destroySession(ctx, token);
  purgeExpiredSessions(ctx);
  return noContent();
};
import { randomBytes, scryptSync, timingSafeEqual } from 'node:crypto';

const KEY_LENGTH = 32;

export function hashPassword(
  password: string,
  cost: number,
  salt: string = randomBytes(16).toString('hex'),
): { hash: string; salt: string } {
  const hash = scryptSync(password, salt, KEY_LENGTH, { N: cost }).toString('hex');
  return { hash, salt };
}

export function verifyPassword(password: string, hash: string, salt: string, cost: number): boolean {
  const candidate = Buffer.from(hashPassword(password, cost, salt).hash, 'hex');
  const expected = Buffer.from(hash, 'hex');
  return candidate.length === expected.length && timingSafeEqual(candidate, expected);
}
import { randomBytes } from 'node:crypto';
import type { AppContext, Session } from '../types.ts';

export function createSession(ctx: AppContext, userId: string): Session {
  const now = ctx.clock.now();
  return ctx.store.sessions.insert({
    id: randomBytes(24).toString('hex'),
    userId,
    createdAt: now.toISOString(),
    expiresAt: new Date(now.getTime() + ctx.config.sessionTtlSeconds * 1000).toISOString(),
  });
}

/** The session for `token`, or undefined when it is unknown or has expired. */
export function findSession(ctx: AppContext, token: string): Session | undefined {
  const session = ctx.store.sessions.get(token);
  if (!session) return undefined;
  if (new Date(session.expiresAt).getTime() <= ctx.clock.now().getTime()) return undefined;
  return session;
}

export function destroySession(ctx: AppContext, token: string): void {
  ctx.store.sessions.delete(token);
}

/** Drop every expired session. Returns how many were removed. */
export function purgeExpiredSessions(ctx: AppContext): number {
  const now = ctx.clock.now().getTime();
  const expired = ctx.store.sessions.find((s) => new Date(s.expiresAt).getTime() <= now);
  for (const session of expired) ctx.store.sessions.delete(session.id);
  return expired.length;
}
