import { authenticateRequest } from './auth/guard.ts';
import { AppError, forbidden, unauthorized } from './lib/errors.ts';
import type { AppContext, User } from './types.ts';

export interface Request {
  method: string;
  path: string;
  query: Record<string, string>;
  headers: Record<string, string>;
  body: unknown;
  params: Record<string, string>;
  /** Filled in by the router for `user` and `admin` routes. */
  user: User | null;
}

export interface Response {
  status: number;
  headers: Record<string, string>;
  body: unknown;
}

export type Handler = (req: Request, ctx: AppContext) => Response;
export type Access = 'public' | 'user' | 'admin';

interface Route {
  method: string;
  segments: string[];
  access: Access;
  handler: Handler;
}

export function json(status: number, body: unknown, headers: Record<string, string> = {}): Response {
  return { status, headers: { 'content-type': 'application/json', ...headers }, body };
}

export const ok = (body: unknown): Response => json(200, body);
export const created = (body: unknown): Response => json(201, body);
export const noContent = (): Response => ({ status: 204, headers: {}, body: null });

function split(path: string): string[] {
  return path.split('/').filter(Boolean);
}

export class Router {
  private routes: Route[] = [];

  add(method: string, pattern: string, access: Access, handler: Handler): void {
    this.routes.push({ method: method.toUpperCase(), segments: split(pattern), access, handler });
  }

  /** Routes are matched in registration order; the first match wins. */
  handle(ctx: AppContext, input: Partial<Request> & { method: string; path: string }): Response {
    const [path, queryString = ''] = input.path.split('?');
    const query = { ...Object.fromEntries(new URLSearchParams(queryString)), ...input.query };
    const headers = Object.fromEntries(
      Object.entries(input.headers ?? {}).map(([k, v]) => [k.toLowerCase(), v]),
    );
    const parts = split(path);
    for (const route of this.routes) {
      if (route.method !== input.method.toUpperCase()) continue;
      const params = matchSegments(route.segments, parts);
      if (!params) continue;
      const req: Request = {
        method: route.method,
        path,
        query,
        headers,
        body: input.body ?? null,
        params,
        user: null,
      };
      try {
        if (route.access !== 'public') {
          req.user = authenticateRequest(ctx, req);
          if (!req.user) throw unauthorized();
          if (route.access === 'admin' && req.user.role !== 'admin') throw forbidden();
        }
        return route.handler(req, ctx);
      } catch (error) {
        if (error instanceof AppError) {
          return json(error.status, { error: { code: error.code, message: error.message } });
        }
        throw error;
      }
    }
    return json(404, { error: { code: 'not_found', message: `no route for ${input.method} ${path}` } });
  }
}

function matchSegments(pattern: string[], actual: string[]): Record<string, string> | null {
  if (pattern.length !== actual.length) return null;
  const params: Record<string, string> = {};
  for (let i = 0; i < pattern.length; i++) {
    if (pattern[i].startsWith(':')) params[pattern[i].slice(1)] = decodeURIComponent(actual[i]);
    else if (pattern[i] !== actual[i]) return null;
  }
  return params;
}
import * as auth from './auth/handlers.ts';
import * as billing from './billing/handlers.ts';
import * as cart from './cart/handlers.ts';
import * as catalog from './catalog/handlers.ts';
import * as inventory from './inventory/handlers.ts';
import * as notifications from './notifications/handlers.ts';
import * as orders from './orders/handlers.ts';
import type { Router } from './router.ts';
import * as shipping from './shipping/handlers.ts';
import * as users from './users/handlers.ts';

/** The one place that knows every endpoint. Routes match in the order they appear here. */
export function registerRoutes(router: Router): void {
  // auth
  router.add('POST', '/auth/login', 'public', auth.login);
  router.add('POST', '/auth/logout', 'user', auth.logout);

  // users
  router.add('POST', '/users', 'public', users.register);
  router.add('GET', '/users/me', 'user', users.me);
  router.add('PATCH', '/users/me', 'user', users.updateMe);
  router.add('POST', '/users/me/addresses', 'user', users.addAddress);

  // catalog
  router.add('GET', '/products', 'public', catalog.list);
  router.add('GET', '/products/:id', 'public', catalog.get);
  router.add('POST', '/products', 'admin', catalog.create);
  router.add('PATCH', '/products/:id', 'admin', catalog.update);

  // cart
  router.add('GET', '/cart', 'user', cart.show);
  router.add('POST', '/cart/items', 'user', cart.addItem);
  router.add('PATCH', '/cart/items/:productId', 'user', cart.setQuantity);
  router.add('DELETE', '/cart/items/:productId', 'user', cart.removeItem);

  // orders
  router.add('POST', '/checkout', 'user', orders.checkout);
  router.add('GET', '/orders', 'user', orders.list);
  router.add('GET', '/orders/:id', 'user', orders.get);
  router.add('POST', '/orders/:id/cancel', 'user', orders.cancel);

  // billing
  router.add('GET', '/orders/:id/invoice', 'user', billing.invoiceForOrder);
  router.add('GET', '/invoices/:id', 'user', billing.getInvoice);
  router.add('POST', '/invoices/:id/pay', 'admin', billing.payInvoice);

  // shipping
  router.add('POST', '/shipping/quote', 'user', shipping.quote);
  router.add('POST', '/orders/:id/ship', 'admin', shipping.shipOrder);
  router.add('GET', '/orders/:id/shipment', 'user', shipping.getShipment);

  // inventory
  router.add('GET', '/inventory/low-stock', 'admin', inventory.lowStock);
  router.add('GET', '/inventory/:productId', 'admin', inventory.get);
  router.add('PUT', '/inventory/:productId', 'admin', inventory.setStock);

  // notifications
  router.add('GET', '/notifications', 'user', notifications.list);
}
import { getCart, priceCart } from '../cart/service.ts';
import { badRequest, notFound } from '../lib/errors.ts';
import { asBody, optionalString, requireInt, requireString } from '../lib/validate.ts';
import { ok } from '../router.ts';
import type { Handler } from '../router.ts';
import type { ShippingMethod } from '../types.ts';
import { getShipment as findShipment, markShipped, quoteForOrder } from './service.ts';

function methodFrom(raw: string | undefined): ShippingMethod {
  if (raw === undefined) return 'standard';
  if (raw !== 'standard' && raw !== 'express') throw badRequest('method must be standard or express');
  return raw;
}

/** Quote shipping for the current cart to one of the user's saved addresses. */
export const quote: Handler = (req, ctx) => {
  const body = asBody(req.body);
  const address = req.user!.addresses[requireInt(body, 'addressIndex')];
  if (!address) throw badRequest('unknown address');
  const priced = priceCart(ctx, getCart(ctx, req.user!.id));
  const lines = priced.lines.map((l) => ({ productId: l.productId, name: l.name, quantity: l.quantity, unitPrice: l.unitPrice }));
  return ok(quoteForOrder(ctx, { lines, shippingAddress: address }, methodFrom(optionalString(body, 'method'))));
};

export const shipOrder: Handler = (req, ctx) => {
  const body = asBody(req.body);
  const order = markShipped(ctx, req.params.id, requireString(body, 'trackingNumber'), methodFrom(optionalString(body, 'method')));
  return ok(order);
};

export const getShipment: Handler = (req, ctx) => {
  const order = ctx.store.orders.require(req.params.id);
  if (order.userId !== req.user!.id && req.user!.role !== 'admin') throw notFound('order');
  const shipment = findShipment(ctx, order.id);
  if (!shipment) throw notFound('shipment');
  return ok({ ...shipment, trackingNumber: order.trackingNumber });
};
import { badRequest } from '../lib/errors.ts';
import type { Address, ShippingMethod, ShippingQuote } from '../types.ts';

/** Base charge in cents by destination zone. */
const ZONE_BASE: Record<string, number> = {
  domestic: 500,
  neighbour: 1200,
  international: 2500,
};

const NEIGHBOURS: Record<string, string> = { US: 'CA', CA: 'US' };

/** Extra cents charged per started kilogram above the first. */
const PER_KG = 150;

const EXPRESS_MULTIPLIER = 2;

export function zoneFor(address: Address, homeCountry: string): 'domestic' | 'neighbour' | 'international' {
  const country = address.country.toUpperCase();
  if (country === homeCountry.toUpperCase()) return 'domestic';
  if (NEIGHBOURS[homeCountry.toUpperCase()] === country) return 'neighbour';
  return 'international';
}

export function quoteShipping(
  address: Address,
  weightKg: number,
  method: ShippingMethod,
  homeCountry: string,
): ShippingQuote {
  if (weightKg <= 0) throw badRequest('nothing to ship');
  const zone = zoneFor(address, homeCountry);
