import { badRequest, conflict } from '../lib/errors.ts';
import { formatMoney, percentOf, sumCents } from '../lib/money.ts';
import type { Cents, Coupon, Currency } from '../types.ts';

/** Check that `coupon` may be used on a cart worth `subtotal`. Returns the coupon for chaining. */
export function validateCoupon(coupon: Coupon, subtotal: Cents, currency: Currency): Coupon {
  if (subtotal < coupon.minSubtotal) {
    throw badRequest(`coupon ${coupon.id} needs a subtotal of at least ${formatMoney(coupon.minSubtotal, currency)}`);
  }
  if (coupon.maxRedemptions !== null && coupon.redemptions >= coupon.maxRedemptions) {
    throw conflict('coupon has been fully redeemed');
  }
  return coupon;
}

/** How much `coupon` takes off a cart worth `subtotal`. */
export function couponDiscount(coupon: Coupon, subtotal: Cents): Cents {
  let discount = coupon.value;
  if (coupon.kind === 'percent') {
    discount = percentOf(subtotal, coupon.value);
    if (coupon.maxDiscount != null) discount = Math.min(discount, coupon.maxDiscount);
  }
  return Math.min(discount, subtotal);
}

/** Spread a cart-level discount over the lines in proportion to their value. */
export function allocateDiscount(nets: Cents[], discount: Cents): Cents[] {
  const subtotal = sumCents(nets);
  if (subtotal === 0) return nets.map(() => 0);
  return nets.map((net) => Math.floor((discount * net) / subtotal));
}
import type { Currency } from './types.ts';

export interface Config {
  storeName: string;
  currency: Currency;
  /** Country assumed when an address has none. */
  defaultCountry: string;
  /** Tax rate used when nothing more specific matches an address. */
  fallbackTaxRate: number;
  sessionTtlSeconds: number;
  /** scrypt cost parameter (N). Kept low so the test suite stays fast. */
  passwordCost: number;
  maxCartLines: number;
  /** Most units of a single product allowed in one order. */
  maxLineQuantity: number;
  lowStockThreshold: number;
  orderNumberPrefix: string;
  pageSize: number;
  /** Days after issue that an invoice falls due. */
  paymentTermsDays: number;
}

export const defaultConfig: Config = {
  storeName: 'Beanstalk Shop',
  currency: 'USD',
  defaultCountry: 'US',
  fallbackTaxRate: 0.07,
  sessionTtlSeconds: 3600,
  passwordCost: 1024,
  maxCartLines: 50,
  maxLineQuantity: 10,
  lowStockThreshold: 5,
  orderNumberPrefix: 'BS',
  pageSize: 20,
  paymentTermsDays: 30,
};

const CURRENCIES = ['USD', 'CAD', 'EUR', 'GBP'];

function intFrom(value: string | undefined, fallback: number): number {
  if (value === undefined || value === '') return fallback;
  const n = Number.parseInt(value, 10);
  if (Number.isNaN(n)) throw new Error(`invalid integer in config: ${value}`);
  return n;
}

/** Build a config from environment-style overrides. Unset keys keep their defaults. */
export function loadConfig(env: Record<string, string | undefined> = {}): Config {
  const currency = env.SHOP_CURRENCY ?? defaultConfig.currency;
  if (!CURRENCIES.includes(currency)) throw new Error(`unsupported currency: ${currency}`);
  return {
    ...defaultConfig,
    storeName: env.SHOP_NAME ?? defaultConfig.storeName,
    currency: currency as Currency,
    defaultCountry: env.SHOP_COUNTRY ?? defaultConfig.defaultCountry,
    sessionTtlSeconds: intFrom(env.SESSION_TTL_SECONDS, defaultConfig.sessionTtlSeconds),
    passwordCost: intFrom(env.PASSWORD_COST, defaultConfig.passwordCost),
    maxCartLines: intFrom(env.MAX_CART_LINES, defaultConfig.maxCartLines),
    maxLineQuantity: intFrom(env.MAX_LINE_QUANTITY, defaultConfig.maxLineQuantity),
    lowStockThreshold: intFrom(env.LOW_STOCK_THRESHOLD, defaultConfig.lowStockThreshold),
    paymentTermsDays: intFrom(env.PAYMENT_TERMS_DAYS, defaultConfig.paymentTermsDays),
  };
}
import { issueInvoice } from '../billing/service.ts';
import { clearCart, getCart, priceCart } from '../cart/service.ts';
import { release, reserve } from '../inventory/stock.ts';
import { badRequest } from '../lib/errors.ts';
import { enqueueNotification } from '../notifications/queue.ts';
import { quoteForOrder } from '../shipping/service.ts';
import type { AppContext, Order, OrderLine, ShippingMethod, User } from '../types.ts';

export interface CheckoutInput {
  /** Index into the user's saved addresses. */
  addressIndex: number;
  couponCode?: string;
  method?: ShippingMethod;
}

/** Turn the user's cart into a confirmed order: reserve stock, invoice it, quote shipping, notify. */
export function checkout(ctx: AppContext, user: User, input: CheckoutInput): Order {
  const address = user.addresses[input.addressIndex];
  if (!address) throw badRequest('choose a saved shipping address');
  const cart = getCart(ctx, user.id);
  if (cart.lines.length === 0) throw badRequest('cart is empty');
  const priced = priceCart(ctx, cart);

  const limit = ctx.config.maxLineQuantity;
  const perProduct = new Map<string, number>();
  for (const line of priced.lines) {
    const total = (perProduct.get(line.productId) ?? 0) + line.quantity;
    perProduct.set(line.productId, total);
    if (total > limit) throw badRequest(`at most ${limit} units of ${line.name} per order`);
  }

  reserve(ctx, cart.lines);
  try {
    return placeOrder(ctx, user, input, address, cart, priced);
  } catch (error) {
    release(ctx, cart.lines);
    throw error;
  }
}

function placeOrder(
  ctx: AppContext,
  user: User,
  input: CheckoutInput,
  address: User['addresses'][number],
  cart: ReturnType<typeof getCart>,
  priced: ReturnType<typeof priceCart>,
): Order {
  const orderId = ctx.store.nextId('ord');
  const invoice = issueInvoice(ctx, {
    orderId,
    userId: user.id,
    address,
    couponCode: input.couponCode,
    items: priced.lines.map((line) => ({
      productId: line.productId,
      description: line.name,
      quantity: line.quantity,
      unitPrice: line.unitPrice,
      taxClass: line.product.taxClass,
    })),
  });

  const lines: OrderLine[] = priced.lines.map((line) => ({
    productId: line.productId,
    name: line.name,
    quantity: line.quantity,
    unitPrice: line.unitPrice,
  }));
  const shipping = quoteForOrder(ctx, { lines, shippingAddress: address }, input.method ?? 'standard');
  const now = ctx.clock.now().toISOString();
  const order = ctx.store.orders.insert({
    id: orderId,
    number: `${ctx.config.orderNumberPrefix}-${orderId.slice(4)}`,
    userId: user.id,
    status: 'confirmed',
    lines,
    subtotal: invoice.subtotal,
    discount: invoice.discount,
    tax: invoice.tax,
    shippingCost: shipping.cost,
    total: invoice.total,
    couponCode: invoice.couponCode,
    shippingAddress: address,
    invoiceId: invoice.id,
    trackingNumber: null,
    createdAt: now,
    updatedAt: now,
  });

  clearCart(ctx, user.id);
  enqueueNotification(ctx, 'order_confirmed', order);
  return order;
}
