import type { Address, TaxClass } from '../types.ts';

/** Combined sales tax by country, then by region (province or state). */
const RATES: Record<string, Record<string, number>> = {
  CA: {
    AB: 0.05,
    BC: 0.12,
    MB: 0.12,
    NB: 0.15,
    NL: 0.15,
    NS: 0.15,
    NT: 0.05,
    NU: 0.05,
    ON: 0.13,
    PE: 0.15,
    QC: 0.14975,
    SK: 0.11,
    YT: 0.05,
  },
  US: {
    CA: 0.0725,
    FL: 0.06,
    NY: 0.04,
    OR: 0,
    TX: 0.0625,
    WA: 0.065,
  },
};

/** Federal part of the combined rate, for countries that levy one. */
const FEDERAL_RATES: Record<string, number> = { CA: 0.05 };

/** Share of the full rate charged on `reduced` goods such as food. */
const REDUCED_SHARE = 0.5;

/**
 * The tax rate (a fraction, 0.13 = 13%) that applies to goods of `taxClass`
 * shipped to `address`. Unknown regions fall back to `fallback`.
 */
export function taxRateFor(address: Address, taxClass: TaxClass, fallback: number): number {
  if (taxClass === 'exempt') return 0;
  const country = address.country.toUpperCase();
  const region = address.region.toUpperCase();
  const full = RATES[country]?.[region] ?? fallback;
  return taxClass === 'reduced' ? full * REDUCED_SHARE : full;
}

/**
 * The federal and regional parts (fractions) of the rate `taxRateFor` returns.
 * Without a federal entry for the country, everything is regional.
 */
export function taxComponentsFor(
  address: Address,
  taxClass: TaxClass,
  fallback: number,
): { federal: number; regional: number } {
  const country = address.country.toUpperCase();
  const region = address.region.toUpperCase();
  const known = RATES[country]?.[region];
  const share = taxClass === 'exempt' ? 0 : taxClass === 'reduced' ? REDUCED_SHARE : 1;
  if (known === undefined) return { federal: 0, regional: fallback * share };
  const federal = Math.min(FEDERAL_RATES[country] ?? 0, known);
  const regional = Math.round((known - federal) * 1e6) / 1e6;
  return { federal: federal * share, regional: regional * share };
}
