import { issueInvoice } from '../billing/service.ts';
import { clearCart, getCart, priceCart } from '../cart/service.ts';
import { release, reserve } from '../inventory/stock.ts';
import { badRequest } from '../lib/errors.ts';
import { enqueueNotification } from '../notifications/queue.ts';
import { quoteForOrder } from '../shipping/service.ts';
import type { AppContext, Order, OrderLine, ShippingMethod, User } from '../types.ts';

export interface CheckoutInput {
  /** Index into the user's saved addresses. */
  addressIndex: number;
  couponCode?: string;
  method?: ShippingMethod;
  note?: string;
}

/** Turn the user's cart into a confirmed order: reserve stock, invoice it, quote shipping, notify. */
export function checkout(ctx: AppContext, user: User, input: CheckoutInput): Order {
  const address = user.addresses[input.addressIndex];
  if (!address) throw badRequest('choose a saved shipping address');
  const cart = getCart(ctx, user.id);
  if (cart.lines.length === 0) throw badRequest('cart is empty');
  const priced = priceCart(ctx, cart);

  const limit = ctx.config.maxLineQuantity;
  const perProduct = new Map<string, number>();
  for (const line of priced.lines) {
    const total = (perProduct.get(line.productId) ?? 0) + line.quantity;
    perProduct.set(line.productId, total);
    if (total > limit) throw badRequest(`at most ${limit} units of ${line.name} per order`);
  }

  reserve(ctx, cart.lines);
  try {
    return placeOrder(ctx, user, input, address, cart, priced);
  } catch (error) {
    release(ctx, cart.lines);
    throw error;
  }
}

function placeOrder(
  ctx: AppContext,
  user: User,
  input: CheckoutInput,
  address: User['addresses'][number],
  cart: ReturnType<typeof getCart>,
  priced: ReturnType<typeof priceCart>,
): Order {
  const orderId = ctx.store.nextId('ord');
  const invoice = issueInvoice(ctx, {
    orderId,
    userId: user.id,
    address,
    couponCode: input.couponCode,
    items: priced.lines.map((line) => ({
      productId: line.productId,
      description: line.name,
      quantity: line.quantity,
      unitPrice: line.unitPrice,
      taxClass: line.product.taxClass,
    })),
  });

  const lines: OrderLine[] = priced.lines.map((line) => ({
    productId: line.productId,
    name: line.name,
    quantity: line.quantity,
    unitPrice: line.unitPrice,
  }));
  const shipping = quoteForOrder(ctx, { lines, shippingAddress: address }, input.method ?? 'standard');
  const now = ctx.clock.now().toISOString();
  const order = ctx.store.orders.insert({
    id: orderId,
    number: `${ctx.config.orderNumberPrefix}-${orderId.slice(4)}`,
    userId: user.id,
    status: 'confirmed',
    lines,
    subtotal: invoice.subtotal,
    discount: invoice.discount,
    tax: invoice.tax,
    shippingCost: shipping.cost,
    total: invoice.total,
    couponCode: invoice.couponCode,
    shippingAddress: address,
    invoiceId: invoice.id,
    note: input.note ?? '',
    createdAt: now,
    updatedAt: now,
  });

  clearCart(ctx, user.id);
  enqueueNotification(ctx, 'order_confirmed', order);
  return order;
}
import { getCart, priceCart } from '../cart/service.ts';
import { badRequest, notFound } from '../lib/errors.ts';
import { asBody, optionalString, requireInt, requireString } from '../lib/validate.ts';
import { ok } from '../router.ts';
import type { Handler } from '../router.ts';
import type { ShippingMethod } from '../types.ts';
import { getShipment as findShipment, markShipped, quoteForOrder } from './service.ts';

function methodFrom(raw: string | undefined): ShippingMethod {
  if (raw === undefined) return 'standard';
  if (raw !== 'standard' && raw !== 'express') throw badRequest('method must be standard or express');
  return raw;
}

/** Quote shipping for the current cart to one of the user's saved addresses. */
export const quote: Handler = (req, ctx) => {
  const body = asBody(req.body);
  const address = req.user!.addresses[requireInt(body, 'addressIndex')];
  if (!address) throw badRequest('unknown address');
  const priced = priceCart(ctx, getCart(ctx, req.user!.id));
  const lines = priced.lines.map((l) => ({ productId: l.productId, name: l.name, quantity: l.quantity, unitPrice: l.unitPrice }));
  return ok(quoteForOrder(ctx, { lines, shippingAddress: address }, methodFrom(optionalString(body, 'method'))));
};

export const shipOrder: Handler = (req, ctx) => {
  const body = asBody(req.body);
  const order = markShipped(ctx, req.params.id, requireString(body, 'trackingNumber'), methodFrom(optionalString(body, 'method')));
  return ok(order);
};

export const getShipment: Handler = (req, ctx) => {
  const order = ctx.store.orders.require(req.params.id);
  if (order.userId !== req.user!.id && req.user!.role !== 'admin') throw notFound('order');
  const shipment = findShipment(ctx, order.id);
  if (!shipment) throw notFound('shipment');
  return ok(shipment);
};
import { enqueueNotification } from '../notifications/queue.ts';
import { badRequest, conflict } from '../lib/errors.ts';
import type { AppContext, Order, Shipment, ShippingMethod, ShippingQuote } from '../types.ts';
import { quoteShipping } from './rates.ts';

/** Goods total (in cents) at or above which standard shipping is free. */
export const FREE_SHIPPING_THRESHOLD = 7500;

/** Weight of an order's lines, from current catalog data. */
export function orderWeight(ctx: AppContext, order: Pick<Order, 'lines'>): number {
  return order.lines.reduce((kg, line) => {
    const product = ctx.store.products.get(line.productId);
    return kg + (product?.weightKg ?? 0.5) * line.quantity;
  }, 0);
}

export function quoteForOrder(
  ctx: AppContext,
  order: Pick<Order, 'lines' | 'shippingAddress'>,
  method: ShippingMethod = 'standard',
): ShippingQuote {
  const quote = quoteShipping(order.shippingAddress, orderWeight(ctx, order), method, ctx.config.defaultCountry);
  const goods = order.lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0);
  if (method === 'standard' && goods >= FREE_SHIPPING_THRESHOLD) return { ...quote, cost: 0 };
  return quote;
}

export function getShipment(ctx: AppContext, orderId: string): Shipment | undefined {
  return ctx.store.shipments.findOne((s) => s.orderId === orderId);
}

/** Record the shipment for an order and mark the order as shipped. */
export function markShipped(ctx: AppContext, orderId: string, trackingNumber: string, method: ShippingMethod = 'standard'): Order {
  const order = ctx.store.orders.require(orderId);
  if (order.status !== 'confirmed') throw conflict(`order ${order.number} is ${order.status}, not confirmed`);
  if (!trackingNumber) throw badRequest('tracking number is required');
  const now = ctx.clock.now().toISOString();
  ctx.store.shipments.insert({
    id: ctx.store.nextId('shp'),
    orderId,
    method,
    cost: order.shippingCost,
    status: 'shipped',
    trackingNumber,
    shippedAt: now,
  });
  const updated = ctx.store.orders.update(orderId, { status: 'shipped', updatedAt: now });
  enqueueNotification(ctx, 'order_shipped', updated);
  return updated;
}
