/** Customers only see their own invoices; admins see all. Anything else looks like a 404. */
function visibleTo(user: User, invoice: Invoice): Invoice {
  if (invoice.userId !== user.id && user.role !== 'admin') throw notFound('invoice');
  return invoice;
}

export const getInvoice: Handler = (req, ctx) => ok(visibleTo(req.user!, loadInvoice(ctx, req.params.id)));

export const getInvoiceText: Handler = (req, ctx) => {
  const invoice = visibleTo(req.user!, loadInvoice(ctx, req.params.id));
  const money = (amount: number) => formatMoney(amount, invoice.currency);
  const lines = [
    `Invoice ${invoice.number}`,
    ...invoice.lines.map((l) => `${l.quantity} x ${l.description} - ${money(l.net)}`),
    `Subtotal: ${money(invoice.subtotal)}`,
    ...(invoice.discount > 0 ? [`Discount: ${money(-invoice.discount)}`] : []),
    `Tax: ${money(invoice.tax)}`,
    `Total: ${money(invoice.total)}`,
  ];
  return { status: 200, headers: { 'content-type': 'text/plain; charset=utf-8' }, body: lines.join('\n') };
};

export const invoiceForOrder: Handler = (req, ctx) =>
  ok(visibleTo(req.user!, loadInvoiceForOrder(ctx, req.params.id)));

export const listInvoices: Handler = (req, ctx) => {
  const { status } = req.query;
  if (status !== undefined && status !== 'open' && status !== 'paid' && status !== 'void') {
    throw badRequest('status must be open, paid or void');
  }
  const { items, total } = paginate(loadInvoices(ctx, req.user!.id, status), req.query, ctx.config.pageSize);
  return json(200, items, { 'x-total-count': String(total) });
};

export const overdueInvoices: Handler = (_req, ctx) => ok(loadOverdue(ctx));

export const payInvoice: Handler = (req, ctx) => ok(markPaid(ctx, req.params.id));

export const refundLine: Handler = (req, ctx) =>
  json(201, issueRefund(ctx, req.params.id, requireString(asBody(req.body), 'productId')));
