import { describe, it } from 'node:test';
import { addProduct, createTestApp, ON_ADDRESS, signUp } from '../lib/testing.ts';
import type { Invoice, Order } from '../types.ts';
import { markPaid } from './service.ts';

function threeLineOrder() {
  const app = createTestApp();
  const customer = signUp(app.ctx, 'buyer@example.com', { address: ON_ADDRESS });
  const admin = signUp(app.ctx, 'admin@example.com', { admin: true });
  const products = [333, 333, 333].map((price) => addProduct(app.ctx, { price }));
  for (const p of products) {
    app.call('POST', '/cart/items', { token: customer.token, body: { productId: p.id, quantity: 1 } });
  }
  const order = app.call('POST', '/checkout', { token: customer.token, body: { addressIndex: 0 } }).body as Order;
  return { app, customer, admin, products, order };
}

const refund = (t: ReturnType<typeof threeLineOrder>, productId: string, token = t.admin.token) =>
  t.app.call('POST', `/invoices/${t.order.invoiceId}/refunds`, { token, body: { productId } });

describe('line refunds', () => {
  it('refunds a line\'s net plus the tax charged on it', () => {
    const t = threeLineOrder();
    markPaid(t.app.ctx, t.order.invoiceId!);
    const res = refund(t, t.products[0].id);
    assert.equal(res.status, 201);
    assert.equal((res.body as { productId: string }).productId, t.products[0].id);
    assert.equal((res.body as { createdAt: string }).createdAt, '2026-09-15T12:00:00.000Z');
    const invoice = t.app.ctx.store.invoices.require(t.order.invoiceId!) as Invoice;
    assert.equal(invoice.refunds?.length, 1);
    assert.equal(invoice.refunds?.[0].amount, (res.body as { amount: number }).amount);
  });

  it('refunds each line $3.33 plus its share of the invoice tax (43, 43 and 44 cents)', () => {
    const t = threeLineOrder();
    markPaid(t.app.ctx, t.order.invoiceId!);
    const amounts = t.products.map((p) => (refund(t, p.id).body as { amount: number }).amount);
    assert.deepEqual([...amounts].sort(), [376, 376, 377]);
  });

  it('refunding every line returns the whole invoice total', () => {
    const t = threeLineOrder();
    markPaid(t.app.ctx, t.order.invoiceId!);
    const amounts = t.products.map((p) => (refund(t, p.id).body as { amount: number }).amount);
    assert.equal(amounts.reduce((a, b) => a + b, 0), t.app.ctx.store.invoices.require(t.order.invoiceId!).total);
  });

  it('refuses double refunds, unknown products and unpaid invoices', () => {
    const t = threeLineOrder();
    assert.equal(refund(t, t.products[0].id).status, 409, 'invoice is still open');
    markPaid(t.app.ctx, t.order.invoiceId!);
    assert.equal(refund(t, 'prd_nope').status, 404);
    assert.equal(refund(t, t.products[1].id).status, 201);
    assert.equal(refund(t, t.products[1].id).status, 409);
  });

  it('is for admins only', () => {
    const t = threeLineOrder();
    markPaid(t.app.ctx, t.order.invoiceId!);
    assert.equal(refund(t, t.products[0].id, t.customer.token).status, 403);
  });
});
import { badRequest, conflict, notFound } from '../lib/errors.ts';
import { enqueueNotification } from '../notifications/queue.ts';
import type { AppContext, Coupon, Invoice, InvoiceRefund } from '../types.ts';
import { buildInvoice } from './invoice.ts';
import type { InvoiceInput } from './invoice.ts';

export function findCoupon(ctx: AppContext, code: string): Coupon | undefined {
  return ctx.store.coupons.get(code.trim().toUpperCase());
}

export type InvoiceRequest = Omit<InvoiceInput, 'coupon'> & { couponCode?: string };

/** Price an order, persist the invoice and count the coupon redemption. */
export function issueInvoice(ctx: AppContext, request: InvoiceRequest): Invoice {
  const { couponCode, ...rest } = request;
  const coupon = couponCode ? findCoupon(ctx, couponCode) : undefined;
  if (couponCode && !coupon) throw badRequest('unknown coupon code');
  const draft = buildInvoice(ctx, { ...rest, coupon });
  const id = ctx.store.nextId('inv');
  const year = draft.issuedAt.slice(0, 4);
  const sequence = ctx.store.invoices.all().filter((i) => i.number.startsWith(`INV-${year}-`)).length + 1;
  const number = `INV-${year}-${String(sequence).padStart(4, '0')}`;
  const invoice = ctx.store.invoices.insert({ ...draft, id, number });
  if (coupon) ctx.store.coupons.update(coupon.id, { redemptions: coupon.redemptions + 1 });
  return invoice;
}

export function getInvoice(ctx: AppContext, id: string): Invoice {
  return ctx.store.invoices.require(id);
}

export function listInvoices(ctx: AppContext, userId: string, status?: Invoice['status']): Invoice[] {
  return ctx.store.invoices
    .find((i) => i.userId === userId && (status === undefined || i.status === status))
    .sort((a, b) => b.issuedAt.localeCompare(a.issuedAt) || b.id.localeCompare(a.id));
}

/** Open invoices past their due date, longest overdue first. */
export function overdueInvoices(ctx: AppContext): (Invoice & { daysOverdue: number })[] {
  const now = ctx.clock.now().getTime();
  return ctx.store.invoices
    .find((i) => i.status === 'open' && Date.parse(i.dueAt) < now)
    .sort((a, b) => a.dueAt.localeCompare(b.dueAt) || a.id.localeCompare(b.id))
    .map((i) => ({ ...i, daysOverdue: Math.max(1, Math.floor((now - Date.parse(i.dueAt)) / 86_400_000)) }));
}

export function invoiceForOrder(ctx: AppContext, orderId: string): Invoice {
  const invoice = ctx.store.invoices.findOne((i) => i.orderId === orderId);
  if (!invoice) throw notFound('invoice');
  return invoice;
}

export function markPaid(ctx: AppContext, id: string): Invoice {
  const invoice = getInvoice(ctx, id);
  if (invoice.status !== 'open') throw conflict(`invoice ${invoice.number} is ${invoice.status}`);
  const paid = ctx.store.invoices.update(id, { status: 'paid', paidAt: ctx.clock.now().toISOString() });
  enqueueNotification(ctx, 'payment_received', ctx.store.orders.require(paid.orderId));
  return paid;
}

/** Refund one whole line: its net, less its share of the order discount, plus the tax charged on it. */
export function refundLine(ctx: AppContext, id: string, productId: string): InvoiceRefund {
  const invoice = getInvoice(ctx, id);
  if (invoice.status !== 'paid') throw conflict(`invoice ${invoice.number} is ${invoice.status}`);
  const line = invoice.lines.find((l) => l.productId === productId);
  if (!line) throw notFound('invoice line');
  const refunds = invoice.refunds ?? [];
  if (refunds.some((r) => r.productId === productId)) throw conflict('line is already refunded');
  const refund = {
    productId,
    amount: line.net - line.discount + line.tax,
    createdAt: ctx.clock.now().toISOString(),
  };
  ctx.store.invoices.update(id, { refunds: [...refunds, refund] });
  return refund;
}

export function voidInvoice(ctx: AppContext, id: string): Invoice {
  const invoice = getInvoice(ctx, id);
  if (invoice.status === 'paid') throw conflict(`invoice ${invoice.number} is already paid`);
  return ctx.store.invoices.update(id, { status: 'void' });
}
