export interface Config {
  storeName: string;
  currency: Currency;
  /** Country assumed when an address has none. */
  defaultCountry: string;
  /** Tax rate used when nothing more specific matches an address. */
  fallbackTaxRate: number;
  sessionTtlSeconds: number;
  /** scrypt cost parameter (N). Kept low so the test suite stays fast. */
  passwordCost: number;
  maxCartLines: number;
  /** Most units of a single product allowed in one order. */
  maxLineQuantity: number;
  lowStockThreshold: number;
  orderNumberPrefix: string;
  pageSize: number;
  /** Days after issue that an invoice falls due. */
  paymentTermsDays: number;
  /** Order total (in cents) at or above which delivery needs a signature. */
  signatureThreshold: number;
}

export const defaultConfig: Config = {
  storeName: 'Beanstalk Shop',
  currency: 'USD',
  defaultCountry: 'US',
  fallbackTaxRate: 0.07,
  sessionTtlSeconds: 3600,
  passwordCost: 1024,
  maxCartLines: 50,
  maxLineQuantity: 10,
  lowStockThreshold: 5,
  orderNumberPrefix: 'BS',
  pageSize: 20,
  paymentTermsDays: 30,
  signatureThreshold: 25000,
};

const CURRENCIES = ['USD', 'CAD', 'EUR', 'GBP'];

function intFrom(value: string | undefined, fallback: number): number {
  if (value === undefined || value === '') return fallback;
  const n = Number.parseInt(value, 10);
  if (Number.isNaN(n)) throw new Error(`invalid integer in config: ${value}`);
  return n;
}

/** Build a config from environment-style overrides. Unset keys keep their defaults. */
export function loadConfig(env: Record<string, string | undefined> = {}): Config {
  const currency = env.SHOP_CURRENCY ?? defaultConfig.currency;
  if (!CURRENCIES.includes(currency)) throw new Error(`unsupported currency: ${currency}`);
  return {
    ...defaultConfig,
    storeName: env.SHOP_NAME ?? defaultConfig.storeName,
    currency: currency as Currency,
    defaultCountry: env.SHOP_COUNTRY ?? defaultConfig.defaultCountry,
    sessionTtlSeconds: intFrom(env.SESSION_TTL_SECONDS, defaultConfig.sessionTtlSeconds),
    passwordCost: intFrom(env.PASSWORD_COST, defaultConfig.passwordCost),
    maxCartLines: intFrom(env.MAX_CART_LINES, defaultConfig.maxCartLines),
    maxLineQuantity: intFrom(env.MAX_LINE_QUANTITY, defaultConfig.maxLineQuantity),
    lowStockThreshold: intFrom(env.LOW_STOCK_THRESHOLD, defaultConfig.lowStockThreshold),
    paymentTermsDays: intFrom(env.PAYMENT_TERMS_DAYS, defaultConfig.paymentTermsDays),
    signatureThreshold: intFrom(env.SIGNATURE_THRESHOLD, defaultConfig.signatureThreshold),
  };
}
import { enqueueNotification } from '../notifications/queue.ts';
import { badRequest, conflict } from '../lib/errors.ts';
import type { AppContext, Order, Shipment, ShippingMethod, ShippingQuote } from '../types.ts';
import { quoteShipping } from './rates.ts';

/** Goods total (in cents) at or above which standard shipping is free. */
export const FREE_SHIPPING_THRESHOLD = 7500;

/** Weight of an order's lines, from current catalog data. */
export function orderWeight(ctx: AppContext, order: Pick<Order, 'lines'>): number {
  return order.lines.reduce((kg, line) => {
    const product = ctx.store.products.get(line.productId);
    return kg + (product?.weightKg ?? 0.5) * line.quantity;
  }, 0);
}

export function quoteForOrder(
  ctx: AppContext,
  order: Pick<Order, 'lines' | 'shippingAddress'>,
  method: ShippingMethod = 'standard',
): ShippingQuote {
  const quote = quoteShipping(order.shippingAddress, orderWeight(ctx, order), method, ctx.config.defaultCountry);
  const goods = order.lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0);
  if (method === 'standard' && goods >= FREE_SHIPPING_THRESHOLD) return { ...quote, cost: 0 };
  return quote;
}

export function getShipment(ctx: AppContext, orderId: string): Shipment | undefined {
  return ctx.store.shipments.findOne((s) => s.orderId === orderId);
}

/** Record the shipment for an order and mark the order as shipped. */
export function markShipped(ctx: AppContext, orderId: string, trackingNumber: string, method: ShippingMethod = 'standard'): Order {
  const order = ctx.store.orders.require(orderId);
  if (order.status !== 'confirmed') throw conflict(`order ${order.number} is ${order.status}, not confirmed`);
  if (!trackingNumber) throw badRequest('tracking number is required');
  const now = ctx.clock.now().toISOString();
  ctx.store.shipments.insert({
    id: ctx.store.nextId('shp'),
    orderId,
    method,
    cost: order.shippingCost,
    status: 'shipped',
    trackingNumber,
    shippedAt: now,
    signatureRequired: order.total >= ctx.config.signatureThreshold,
  });
  const updated = ctx.store.orders.update(orderId, { status: 'shipped', updatedAt: now });
  enqueueNotification(ctx, 'order_shipped', updated);
  return updated;
}
