import { asBody, optionalString, requireInt } from '../lib/validate.ts';
import { created, json, ok } from '../router.ts';
import type { Handler } from '../router.ts';
import type { ShippingMethod } from '../types.ts';
import { checkout as placeOrder } from './checkout.ts';
import { cancelOrder, getVisibleOrder, listOrders } from './service.ts';

export const checkout: Handler = (req, ctx) => {
  const body = asBody(req.body);
  const method = optionalString(body, 'method');
  if (method !== undefined && method !== 'standard' && method !== 'express') {
    throw badRequest('method must be standard or express');
  }
  const order = placeOrder(ctx, req.user!, {
    addressIndex: requireInt(body, 'addressIndex'),
    couponCode: optionalString(body, 'couponCode'),
    method: method as ShippingMethod | undefined,
  });
  return created(order);
};

export const list: Handler = (req, ctx) => {
  const { items, total } = paginate(listOrders(ctx, req.user!.id), req.query, ctx.config.pageSize);
  return json(200, items, { 'x-total-count': String(total) });
};

export const get: Handler = (req, ctx) => ok(getVisibleOrder(ctx, req.user!, req.params.id));

export const cancel: Handler = (req, ctx) => ok(cancelOrder(ctx, req.user!, req.params.id));
import { badRequest, conflict, notFound } from '../lib/errors.ts';
import { enqueueNotification } from '../notifications/queue.ts';
import type { AppContext, Coupon, Invoice } from '../types.ts';
import { buildInvoice } from './invoice.ts';
import type { InvoiceInput } from './invoice.ts';

export function findCoupon(ctx: AppContext, code: string): Coupon | undefined {
  return ctx.store.coupons.get(code.trim().toUpperCase());
}

export type InvoiceRequest = Omit<InvoiceInput, 'coupon'> & { couponCode?: string };

/** Price an order, persist the invoice and count the coupon redemption. */
export function issueInvoice(ctx: AppContext, request: InvoiceRequest): Invoice {
  const { couponCode, ...rest } = request;
  const coupon = couponCode ? findCoupon(ctx, couponCode) : undefined;
  if (couponCode && !coupon) throw badRequest('unknown coupon code');
  const draft = buildInvoice(ctx, { ...rest, coupon });
  const id = ctx.store.nextId('inv');
  const invoice = ctx.store.invoices.insert({ ...draft, id, number: `INV-${id.slice(4)}` });
  if (coupon) ctx.store.coupons.update(coupon.id, { redemptions: coupon.redemptions + 1 });
  return invoice;
}

export function getInvoice(ctx: AppContext, id: string): Invoice {
  return ctx.store.invoices.require(id);
}

export function invoiceForOrder(ctx: AppContext, orderId: string): Invoice {
  const invoice = ctx.store.invoices.findOne((i) => i.orderId === orderId);
  if (!invoice) throw notFound('invoice');
  return invoice;
}

export function markPaid(ctx: AppContext, id: string): Invoice {
  const invoice = getInvoice(ctx, id);
  if (invoice.status !== 'open') throw conflict(`invoice ${invoice.number} is ${invoice.status}`);
  const paid = ctx.store.invoices.update(id, { status: 'paid', paidAt: ctx.clock.now().toISOString() });
  enqueueNotification(ctx, 'payment_received', ctx.store.orders.require(paid.orderId));
  return paid;
}

export function voidInvoice(ctx: AppContext, id: string): Invoice {
  const invoice = getInvoice(ctx, id);
  if (invoice.status === 'paid') throw conflict(`invoice ${invoice.number} is already paid`);
  return ctx.store.invoices.update(id, { status: 'void' });
}
import { formatMoney } from '../lib/money.ts';
import type { Currency, NotificationKind, Order } from '../types.ts';

export interface Rendered {
  subject: string;
  body: string;
}

export function renderNotification(kind: NotificationKind, order: Order, currency: Currency): Rendered {
  switch (kind) {
    case 'order_confirmed': {
      const lines = order.lines.map(
        (line) => `${line.quantity} x ${line.name} - ${formatMoney(line.unitPrice * line.quantity, currency)}`,
      );
      return {
        subject: `Order ${order.number} confirmed`,
        body: ['Thanks for your order!', ...lines, `Total: ${formatMoney(order.total, currency)}`].join('\n'),
      };
    }
    case 'order_shipped':
      return {
        subject: `Order ${order.number} has shipped`,
        body: `Your order ${order.number} is on its way.`,
      };
    case 'order_cancelled':
      return {
        subject: `Order ${order.number} was cancelled`,
        body: `Your order ${order.number} was cancelled. Any payment will be refunded.`,
      };
    case 'payment_received':
      return {
        subject: `Payment received for order ${order.number}`,
        body: `We have received your payment for order ${order.number}. Thank you!`,
      };
  }
}
