/** A user as exposed over the API: no credentials. */
export type PublicUser = Omit<User, 'passwordHash' | 'passwordSalt'>;

export function toPublic(user: User): PublicUser {
  const { passwordHash: _hash, passwordSalt: _salt, ...rest } = user;
  return rest;
}

export function findByEmail(ctx: AppContext, email: string): User | undefined {
  return ctx.store.users.findOne((u) => u.email === email.trim());
}

export function registerUser(ctx: AppContext, input: RegisterInput): User {
  const email = input.email.trim();
  if (!email.includes('@')) throw badRequest('email is invalid');
  if (findByEmail(ctx, email)) throw conflict('email is already registered');
  const { hash, salt } = hashPassword(input.password, ctx.config.passwordCost);
  return ctx.store.users.insert({
    id: ctx.store.nextId('usr'),
    email,
    name: input.name.trim(),
    role: 'customer',
    taxExempt: false,
    passwordHash: hash,
    passwordSalt: salt,
    addresses: [],
    createdAt: ctx.clock.now().toISOString(),
  });
}

export function updateProfile(ctx: AppContext, userId: string, patch: { name?: string }): User {
  const changes: Partial<User> = {};
  if (patch.name !== undefined) {
    if (patch.name === '') throw badRequest('name cannot be empty');
    changes.name = patch.name;
  }
  return ctx.store.users.update(userId, changes);
}

export function addAddress(ctx: AppContext, userId: string, address: Address): User {
  const user = ctx.store.users.require(userId);
  return ctx.store.users.update(userId, { addresses: [...user.addresses, address] });
}
import { applyRate, sumCents } from '../lib/money.ts';
import type { Address, AppContext, Cents, Coupon, Invoice, InvoiceLine, TaxClass } from '../types.ts';
import { allocateDiscount, couponDiscount, validateCoupon } from './discounts.ts';
import { taxRateFor } from './tax.ts';

export interface InvoiceItem {
  productId: string;
  description: string;
  quantity: number;
  unitPrice: Cents;
  taxClass: TaxClass;
}

export interface InvoiceInput {
  orderId: string;
  userId: string;
  address: Address;
  items: InvoiceItem[];
  coupon?: Coupon;
}

export type InvoiceDraft = Omit<Invoice, 'id' | 'number'>;

const DAY_MS = 24 * 60 * 60 * 1000;

/** Price an order: line nets, the coupon, tax per line, and the due date. Pure apart from the clock. */
export function buildInvoice(ctx: AppContext, input: InvoiceInput): InvoiceDraft {
  const nets = input.items.map((item) => item.quantity * item.unitPrice);
  const subtotal = sumCents(nets);
  const coupon = input.coupon ? validateCoupon(input.coupon, subtotal, ctx.config.currency) : undefined;
  const discount = coupon ? couponDiscount(coupon, subtotal) : 0;
  const lineDiscounts = allocateDiscount(nets, discount);

  const lines: InvoiceLine[] = input.items.map((item, i) => {
    const taxRate = taxRateFor(input.address, item.taxClass, ctx.config.fallbackTaxRate);
    return {
      productId: item.productId,
      description: item.description,
      quantity: item.quantity,
      unitPrice: item.unitPrice,
      net: nets[i],
      discount: lineDiscounts[i],
      taxRate,
      tax: applyRate(nets[i] - lineDiscounts[i], taxRate),
    };
  });

  const tax = sumCents(lines.map((line) => line.tax));
  const issuedAt = ctx.clock.now();
  return {
    orderId: input.orderId,
    userId: input.userId,
    currency: ctx.config.currency,
    lines,
    subtotal,
    discount,
    couponCode: coupon?.id ?? null,
    tax,
    total: subtotal - discount + tax,
    status: 'open',
    issuedAt: issuedAt.toISOString(),
    dueAt: new Date(issuedAt.getTime() + ctx.config.paymentTermsDays * DAY_MS).toISOString(),
    paidAt: null,
  };
}
import { badRequest, conflict } from '../lib/errors.ts';
import type { AppContext, CartLine, StockLevel } from '../types.ts';

export function getStock(ctx: AppContext, productId: string): StockLevel {
  return ctx.store.stock.get(productId) ?? { id: productId, onHand: 0, reserved: 0 };
}

export function availableQuantity(level: StockLevel): number {
  return level.onHand - level.reserved;
}

export function setStock(ctx: AppContext, productId: string, onHand: number): StockLevel {
  if (!Number.isInteger(onHand) || onHand < 0) throw badRequest('onHand must be a non-negative integer');
  const existing = ctx.store.stock.get(productId);
  if (existing) return ctx.store.stock.update(productId, { onHand });
  return ctx.store.stock.insert({ id: productId, onHand, reserved: 0 });
}

/** Hold stock for an order. Fails with 409 if any line cannot be covered. */
export function reserve(ctx: AppContext, lines: CartLine[]): void {
  for (const line of lines) {
    if (availableQuantity(getStock(ctx, line.productId)) < line.quantity) {
      throw conflict(`not enough stock for ${line.productId}`);
    }
  }
  for (const line of lines) {
    const level = getStock(ctx, line.productId);
    setReserved(ctx, level, level.reserved + line.quantity);
  }
}

/** Give held stock back, e.g. when an order is cancelled. */
export function release(ctx: AppContext, lines: CartLine[]): void {
  for (const line of lines) {
    const level = getStock(ctx, line.productId);
    setReserved(ctx, level, Math.max(level.reserved - line.quantity, 0));
  }
}

/** Products whose available quantity is at or below the configured threshold. */
export function lowStock(ctx: AppContext): StockLevel[] {
  return ctx.store.stock
    .find((level) => availableQuantity(level) <= ctx.config.lowStockThreshold)
    .sort((a, b) => availableQuantity(a) - availableQuantity(b));
}

function setReserved(ctx: AppContext, level: StockLevel, reserved: number): void {
  if (ctx.store.stock.get(level.id)) ctx.store.stock.update(level.id, { reserved });
  else ctx.store.stock.insert({ ...level, reserved });
}
