    userId: input.userId,
    currency: ctx.config.currency,
    lines,
    subtotal,
    discount,
    couponCode: coupon?.id ?? null,
    tax,
    total: subtotal - discount + tax,
    status: 'open',
    issuedAt: issuedAt.toISOString(),
