import { badRequest, conflict } from '../lib/errors.ts';
import { formatMoney, percentOf } from '../lib/money.ts';
import type { Cents, Coupon, Currency } from '../types.ts';

/** Check that `coupon` may be used on a cart worth `subtotal`. Returns the coupon for chaining. */
export function validateCoupon(coupon: Coupon, subtotal: Cents, currency: Currency): Coupon {
  if (subtotal < coupon.minSubtotal) {
    throw badRequest(`coupon ${coupon.id} needs a subtotal of at least ${formatMoney(coupon.minSubtotal, currency)}`);
  }
  if (coupon.maxRedemptions !== null && coupon.redemptions >= coupon.maxRedemptions) {
    throw conflict('coupon has been fully redeemed');
  }
  return coupon;
}

/** How much `coupon` takes off a cart worth `subtotal`. */
export function couponDiscount(coupon: Coupon, subtotal: Cents): Cents {
  let discount = coupon.value;
  if (coupon.kind === 'percent') {
    discount = percentOf(subtotal, coupon.value);
    if (coupon.maxDiscount != null) discount = Math.min(discount, coupon.maxDiscount);
  }
  return Math.min(discount, subtotal);
}
import { applyRate, sumCents } from '../lib/money.ts';
import type { Address, AppContext, Cents, Coupon, Invoice, InvoiceLine, TaxClass } from '../types.ts';
import { couponDiscount, validateCoupon } from './coupons.ts';
import { allocateDiscount } from './discounts.ts';
import { taxComponentsFor, taxRateFor } from './tax.ts';

export interface InvoiceItem {
  productId: string;
  description: string;
  quantity: number;
  unitPrice: Cents;
  taxClass: TaxClass;
}

export interface InvoiceInput {
  orderId: string;
  userId: string;
  address: Address;
  items: InvoiceItem[];
  coupon?: Coupon;
}

export type InvoiceDraft = Omit<Invoice, 'id' | 'number'>;

const DAY_MS = 24 * 60 * 60 * 1000;

/** Price one invoice line: net, its share of the discount, the destination's tax rate, and tax on the discounted net. */
export function buildInvoiceLine(ctx: AppContext, address: Address, item: InvoiceItem, discount: Cents): InvoiceLine {
  const net = item.quantity * item.unitPrice;
  const taxRate = taxRateFor(address, item.taxClass, ctx.config.fallbackTaxRate);
  return {
    productId: item.productId,
    description: item.description,
    quantity: item.quantity,
    unitPrice: item.unitPrice,
    net,
    discount,
    taxRate,
    tax: applyRate(net - discount, taxRate),
  };
}

/** Price an order: line nets, the coupon, tax per line, and the due date. Pure apart from the clock. */
export function buildInvoice(ctx: AppContext, input: InvoiceInput): InvoiceDraft {
  const nets = input.items.map((item) => item.quantity * item.unitPrice);
  const subtotal = sumCents(nets);
  const coupon = input.coupon ? validateCoupon(input.coupon, subtotal, ctx.config.currency) : undefined;
  const discount = coupon ? couponDiscount(coupon, subtotal) : 0;
  const lineDiscounts = allocateDiscount(nets, discount);

  const lines: InvoiceLine[] = input.items.map((item, i) => buildInvoiceLine(ctx, input.address, item, lineDiscounts[i]));

  const tax = sumCents(lines.map((line) => line.tax));
  // Federal is rounded per line; regional is the remainder so the parts always add up to `tax`.
  const federal = sumCents(
    lines.map((line, i) => {
      const rate = taxComponentsFor(input.address, input.items[i].taxClass, ctx.config.fallbackTaxRate).federal;
      return Math.min(line.tax, applyRate(line.net - line.discount, rate));
    }),
  );
  const issuedAt = ctx.clock.now();
  return {
    orderId: input.orderId,
    userId: input.userId,
    currency: ctx.config.currency,
    lines,
    subtotal,
    discount,
    couponCode: coupon?.id ?? null,
    tax,
    taxBreakdown: { federal, regional: tax - federal },
    total: subtotal - discount + tax,
    status: 'open',
    issuedAt: issuedAt.toISOString(),
    dueAt: new Date(issuedAt.getTime() + ctx.config.paymentTermsDays * DAY_MS).toISOString(),
    paidAt: null,
  };
}
