import type { AppContext, MailMessage, Mailer, Notification, NotificationKind, Order } from '../types.ts';
import { renderNotification } from './templates.ts';

/** A mailer that just remembers what it was asked to send. */
export function createMemoryMailer(): Mailer & { sent: MailMessage[] } {
  const sent: MailMessage[] = [];
  return {
    sent,
    send(message) {
      sent.push(message);
    },
  };
}

/** Try to send one queued notification. A failing mailer leaves it queued for a later flush. */
export function deliver(ctx: AppContext, notification: Notification): Notification {
  const user = ctx.store.users.get(notification.userId);
  if (!user) return notification;
  try {
    ctx.mailer.send({ to: user.email, subject: notification.subject, body: notification.body });
  } catch {
    return notification;
  }
  return ctx.store.notifications.update(notification.id, {
    status: 'sent',
    sentAt: ctx.clock.now().toISOString(),
  });
}

export function enqueueNotification(ctx: AppContext, kind: NotificationKind, order: Order): Notification {
  const trackingNumber = ctx.store.shipments.findOne((s) => s.orderId === order.id)?.trackingNumber;
  const { subject, body } = renderNotification(kind, order, ctx.config.currency, trackingNumber);
  const queued = ctx.store.notifications.insert({
    id: ctx.store.nextId('ntf'),
    userId: order.userId,
    kind,
    subject,
    body,
    status: 'queued',
    createdAt: ctx.clock.now().toISOString(),
    sentAt: null,
  });
  return deliver(ctx, queued);
}

/** Retry everything still queued. Returns how many went out. */
export function flushNotifications(ctx: AppContext): number {
  const queued = ctx.store.notifications.find((n) => n.status === 'queued');
  return queued.map((n) => deliver(ctx, n)).filter((n) => n.status === 'sent').length;
}

/** A user's notifications, newest first. */
export function listNotifications(ctx: AppContext, userId: string): Notification[] {
  return ctx.store.notifications
    .find((n) => n.userId === userId)
    .sort((a, b) => b.createdAt.localeCompare(a.createdAt) || b.id.localeCompare(a.id));
}
import { formatMoney } from '../lib/money.ts';
import type { Currency, NotificationKind, Order } from '../types.ts';

export interface Rendered {
  subject: string;
  body: string;
}

export type Template = (order: Order, currency: Currency, trackingNumber?: string | null) => Rendered;

export const templates: Record<Exclude<NotificationKind, 'payment_received'>, Template> = {
  order_confirmed: (order, currency) => {
    const lines = order.lines.map(
      (line) => `${line.quantity} x ${line.name} - ${formatMoney(line.unitPrice * line.quantity, currency)}`,
    );
    return {
      subject: `Order ${order.number} confirmed`,
      body: ['Thanks for your order!', ...lines, `Total: ${formatMoney(order.total, currency)}`].join('\n'),
    };
  },
  order_shipped: (order, _currency, trackingNumber) => ({
    subject: `Order ${order.number} has shipped`,
    body: `Your order ${order.number} is on its way.` + (trackingNumber ? `\nTracking number: ${trackingNumber}` : ''),
  }),
  order_cancelled: (order) => ({
    subject: `Order ${order.number} was cancelled`,
    body: `Your order ${order.number} was cancelled. Any payment will be refunded.`,
  }),
};

/** Receipts live outside `templates`, which is the table of order-lifecycle messages. */
export const paymentReceivedTemplate: Template = (order) => ({
  subject: `Payment received for order ${order.number}`,
  body: `We have received your payment for order ${order.number}. Thank you!`,
});

export function renderNotification(kind: NotificationKind, order: Order, currency: Currency, trackingNumber?: string | null): Rendered {
  if (kind === 'payment_received') return paymentReceivedTemplate(order, currency);
  return templates[kind](order, currency, trackingNumber);
}
